class Heroi:
    def __init__(self, nome, vida_max):
        self.nome = nome
        self.vida_max = vida_max
        self._vida = vida_max

    @property
    def vida(self):
        return self._vida

    @vida.setter
    def vida(self, valor):
        if valor < 0:
            valor = 0
        if valor > self.vida_max:
            valor = self.vida_max
        self._vida = valor

    def levar_dano(self, dano):
        self.vida -= dano

    def curar(self, quantidade):
        self.vida += quantidade


