class Bolsa:
    def __init__(self, moedas):
        self.moedas = moedas

    def __repr__(self):
        return f"Bolsa({self.moedas})"

    def total(self):
        return sum(self.moedas)

    def __len__(self):
        return len(self.moedas)

    def __add__(self, outra):
        return Bolsa(self.moedas + outra.moedas)

    def __eq__(self, outra):
        return self.total() == outra.total()

    def __lt__(self, outra):
        return self.total() < outra.total()


a = Bolsa([10, 5, 5])
b = Bolsa([25])
c = Bolsa([1, 1])
print(len(a))
print(a + b)
print(a == Bolsa([20]), a == b)
print(sorted([b, a, c]))

