class Personagem:
    def __init__(self, nome, vida, ataque):
        self.nome = nome
        self.vida = vida
        self.ataque = ataque

    def esta_vivo(self):
        return self.vida > 0

    def receber_dano(self, dano):
        self.vida -= dano
        if self.vida < 0:
            self.vida = 0
        return dano

    def atacar(self, outro):
        return outro.receber_dano(self.ataque)


class Guerreiro(Personagem):
    def __init__(self, nome, vida, ataque, defesa):
        super().__init__(nome, vida, ataque)
        self.defesa = defesa

    def receber_dano(self, dano):
        return super().receber_dano(max(dano - self.defesa, 1))


class Mago(Personagem):
    def __init__(self, nome, vida, ataque, mana):
        super().__init__(nome, vida, ataque)
        self.mana = mana

    def atacar(self, outro):
        if self.mana >= 10:
            self.mana -= 10
            return outro.receber_dano(self.ataque * 2)
        return super().atacar(outro)


def batalha(a, b):
    atacante, defensor = a, b
    while True:
        dano = atacante.atacar(defensor)
        print(f"{atacante.nome} ataca {defensor.nome}: {dano} de dano, {defensor.nome} fica com {defensor.vida}")
        if not defensor.esta_vivo():
            print(f"Vencedor: {atacante.nome}")
            return atacante.nome
        atacante, defensor = defensor, atacante


bia = Guerreiro("Bia", 30, 6, 2)
duda = Mago("Duda", 20, 5, 20)
batalha(bia, duda)
